from lib import *
S = SS('k95')
F1 = [['busybox / :latest / 私有仓库无 tag', 'Always'], ['busybox:1.36', 'IfNotPresent'], ['busybox@sha256:…', 'IfNotPresent']]
F2 = [['镜像在本地,仓库不通', ''], ['IfNotPresent', 'Running'], ['Never', 'Running'], ['Always', 'ErrImagePull → ImagePullBackOff']]
F3 = [['本地没有,仓库不通', ''], ['IfNotPresent', 'ErrImagePull(尝试拉了)'], ['Never', 'ErrImageNeverPull(没拉)']]
F4 = [['节点上 demo:v1 = busybox', 'Pod first'], ['把 tag 改指 nginx', '节点上操作'], ['同样 demo:v1 + IfNotPresent', 'Pod second'], ['两个 imageID 不同', '同 tag 不同镜像']]
PANELS = [('f', 'flow', '拉取策略'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("不写 imagePullPolicy 时,API Server 的准入按镜像引用补默认值:busybox(没写 tag)、busybox:latest、registry.example.com/team/app(没写 tag)都是 Always;busybox:1.36(指定了别的 tag)和 busybox@sha256:…(digest)是 IfNotPresent。", f=fl(F1, cur=[0, 1, 2]), t=tl(S(1), mark=lidx(S(1), 'busybox  ', ':latest', 'registry.example.com'), done=lidx(S(1), 'busybox:1.36 ', 'sha256')), kv=KV([['默认', 'latest 或没 tag → Always,其他 → IfNotPresent'], ['在 API 层补', '写进 Pod spec,kubectl get 就能看到'], ['digest', '不可变,IfNotPresent 就够']], ['默认'])),
    step("镜像 localhost:5999/app:1.0 在节点上已有,但该仓库连不上(localhost:5999 无服务):IfNotPresent 和 Never 的 Pod 直接 running;Always 的 Pod 容器状态 ErrImagePull(failed to pull and unpack image … failed to resolve reference … failed to do request: Head \"https://localhost:5999/…\"),事件依次 Pulling、Failed、ErrImagePull、BackOff(Back-off pulling image),随后是 ImagePullBackOff。对照 docker.io 的 busybox:1.36(节点上有,但连不通 docker.io)+ Always,60 秒后是 ImagePullBackOff,事件里是 DeadlineExceeded——连接不通也不拒绝,要等超时。", f=fl(F2, cur=[3], done=[1, 2]), t=tl(S(2), mark=lidx(S(2), 'always-present(localhost', '对照:busybox:1.36'), done=lidx(S(2), 'ifnp-present', 'never-present')), kv=KV([['Always', '每次创建容器都要访问仓库(校验 digest)'], ['仓库故障', 'Always 的 Pod 起不来,IfNotPresent 的不受影响'], ['超时与拒绝', '不通 = 等超时,拒绝 = 立即失败']], ['Always'])),
    step("本地没有的镜像 localhost:5999/missing:1.0:IfNotPresent 会尝试拉取,失败 → ErrImagePull(Head \"https://localhost:5999/v2/missing/manifests/1.0\" …);Never 不拉取,直接 ErrImageNeverPull,message 是 Container image \"localhost:5999/missing:1.0\" is not present with pull policy of Never,事件里没有 Pulling。", f=fl(F3, cur=[1, 2]), t=tl(S(3), mark=lidx(S(3), 'ifnp-missing(', 'never-missing('), done=lidx(S(3), '对照:never-missing')), kv=KV([['Never', '只用本地的,没有就报 ErrImageNeverPull'], ['IfNotPresent', '本地没有才去拉'], ['预热镜像', 'Never 适合镜像由别的机制提前放好的场景']], ['Never'])),
    step("同一个 tag 可能对应不同的镜像:节点上 demo:v1 原本是 busybox,Pod first 的 imageID 以 …2b865bd036cfddd518839204 结尾;用 ctr images tag --force 把节点上的 demo:v1 改指向 nginx 镜像后,第二个 Pod second 同样写 demo:v1 + IfNotPresent,没有任何拉取事件,imageID 是 …8ba7c98b61c2a856a22b826a。first 里跑的是 BusyBox v1.36.1,second 里是 nginx/1.27.5——同一个 tag、同一个节点、两个 Pod 跑的是不同的镜像。", f=fl(F4, cur=[1, 2], done=[0, 3]), t=tl(S(4), mark=lidx(S(4), '改指向 nginx', 'second 同样写'), done=lidx(S(4), 'first 里是')), kv=KV([['IfNotPresent 只看 tag', '不比较内容'], ['tag 可变', '谁都能让它指向别的镜像'], ['固定 digest', '才能保证“跑的是同一份”']], ['tag 可变'])),
]
A = mkartk('k95', 95, 'Kubernetes,imagePullPolicy,镜像,IfNotPresent,Always,真实验证,动画演示',
    '在 kind 里实测 imagePullPolicy:不写时 API Server 按镜像引用补默认值(无 tag / latest → Always,其他 tag 和 digest → IfNotPresent);镜像在本地而仓库连不上时,IfNotPresent 与 Never 能跑,Always 报 ErrImagePull → ImagePullBackOff;本地没有的镜像,IfNotPresent 尝试拉取失败而 Never 直接 ErrImageNeverPull;同一个 tag 在节点上被改指向别的镜像后,IfNotPresent 的两个 Pod 跑着不同的镜像。',
    'imagePullPolicy 的默认值是怎么来的?Always 是不是每次都下载整个镜像?仓库挂了时哪些 Pod 会受影响?同一个 tag 一定是同一份镜像吗?这篇用一个连不上的仓库和一个被改指向的 tag,把三种策略的行为都跑一遍。',
    [('latest → Always', '不写 tag 或 tag 是 latest 时默认拉取策略;其他 tag 和 digest 是 IfNotPresent'), ('ErrImagePull', '镜像在本地但仓库连不上时,Always 的 Pod 的状态;IfNotPresent 与 Never 的 Pod 照常 Running'), ('同 tag 不同镜像', 'IfNotPresent 只看 tag 在不在,不比较内容;同一节点上两个 Pod 的 imageID 不同')],
    [('默认值', '<p>不写 <code>imagePullPolicy</code> 时,API Server 的准入按镜像引用补默认值:<code>busybox</code>(没写 tag)、<code>busybox:latest</code>、<code>registry.example.com/team/app</code>(没写 tag)是 <code>Always</code>;<code>busybox:1.36</code>(指定了别的 tag)和 <code>busybox@sha256:…</code>(digest)是 <code>IfNotPresent</code>。默认值是在创建对象时由准入写进 Pod spec 的,读出来就能看到。</p>'),
     ('仓库连不上时', '<p>镜像 <code>localhost:5999/app:1.0</code> 在节点上已有,但这个仓库地址没有服务:<code>IfNotPresent</code> 和 <code>Never</code> 的 Pod 直接 <code>Running</code>;<code>Always</code> 的 Pod 容器状态是 <code>ErrImagePull</code>(<code>failed to pull and unpack image … failed to resolve reference … Head "https://localhost:5999/…"</code>),事件依次 <code>Pulling</code>、<code>Failed</code>、<code>ErrImagePull</code>、<code>BackOff</code>(Back-off pulling image),随后是 <code>ImagePullBackOff</code>。<code>Always</code> 并不是每次都下载整个镜像,但每次创建容器都要访问仓库确认 digest,仓库故障时这样的 Pod 起不来。对照 docker.io 的 <code>busybox:1.36</code>(节点上有,但连不通 docker.io)+ <code>Always</code>,60 秒后也是 <code>ImagePullBackOff</code>,事件里是 <code>DeadlineExceeded</code>——连接不通也不拒绝时要等超时才报错。</p>'),
     ('本地没有的镜像', '<p>镜像 <code>localhost:5999/missing:1.0</code> 本地没有:<code>IfNotPresent</code> 会尝试拉取,失败 → <code>ErrImagePull</code>;<code>Never</code> 不拉取,直接 <code>ErrImageNeverPull</code>,message 是 <code>Container image "localhost:5999/missing:1.0" is not present with pull policy of Never</code>,事件里也没有 <code>Pulling</code>。</p>'),
     ('同一个 tag,不同的镜像', '<p>节点上 <code>demo:v1</code> 原本是 busybox,Pod <code>first</code> 的 <code>imageID</code> 以 <code>…2b865bd036cfddd518839204</code> 结尾;用 <code>ctr images tag --force</code> 把节点上的 <code>demo:v1</code> 改指向 nginx 镜像后,第二个 Pod <code>second</code> 同样写 <code>demo:v1</code> + <code>IfNotPresent</code>,没有任何拉取事件,<code>imageID</code> 是 <code>…8ba7c98b61c2a856a22b826a</code>。<code>first</code> 里是 BusyBox v1.36.1,<code>second</code> 里是 nginx/1.27.5。<code>IfNotPresent</code> 只看 tag 在不在,不比较内容;tag 是可变的,固定 digest 才能保证“跑的是同一份”。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0,containerd v2.3.4),Pod 用 nodeName 固定在 worker;“localhost:5999”是不存在的仓库地址(连接立即被拒绝),镜像由 docker tag + kind load 放到节点上;访问 docker.io 的连接在这个环境里是黑洞(不通也不拒绝);改 tag 指向用节点上的 ctr -n k8s.io images tag --force;每种情形各一次',
     '没有验证:imagePullPolicy 在 initContainers / ephemeralContainers 上的行为;kubelet 的 --serialize-image-pulls 与 imagePullProgressDeadline;镜像拉取的 digest 校验(Always 时 manifest 未变就不下载层);ImagePullBackOff 的退避时间(下一篇);AlwaysPullImages 准入(见 k94);镜像垃圾回收对 IfNotPresent 的影响'],
    'imagePullPolicy', PANELS)
